create table if not exists public.ecosystem_providers(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),name text not null,category text not null,description text not null,website text not null check(website ~ '^https://'),stage text not null,industry text not null,needs text[] not null default '{}',area text not null,source text not null,reviewed date not null,status text not null default 'draft' check(status in ('draft','published','archived')),updated_at timestamptz not null default now(),unique(tenant_id,name)); alter table public.ecosystem_providers enable row level security; revoke all on public.ecosystem_providers from public,anon,authenticated; grant select on public.ecosystem_providers to anon,authenticated; grant insert,update on public.ecosystem_providers to authenticated; create policy ecosystem_public_read on public.ecosystem_providers for select to anon,authenticated using(tenant_id=private.current_tenant() and status='published'); create policy ecosystem_staff_read on public.ecosystem_providers for select to authenticated using(tenant_id=private.current_tenant() and public.user_is_admin()); create policy ecosystem_staff_insert on public.ecosystem_providers for insert to authenticated with check(tenant_id=private.current_tenant() and public.user_is_admin()); create policy ecosystem_staff_update on public.ecosystem_providers for update to authenticated using(tenant_id=private.current_tenant() and public.user_is_admin()) with check(tenant_id=private.current_tenant() and public.user_is_admin()); with src(name,category,description,website,stage,industry,needs,area) as(values ('KCSourceLink','Business advising','Connects entrepreneurs with local assistance and a searchable regional resource network.','https://www.kcsourcelink.com/the-resource-navigator/','All stages','All industries','Find business support; referrals; funding guidance','KC metro'),('Missouri SBDC at UMKC','Business advising','Individual business consulting, training and help finding professional resources.','https://sbdc.umkc.edu/','All stages','All industries','Business planning; training; growth','Missouri'),('Kansas SBDC at JCCC','Business advising','Confidential small-business advising and startup guidance for Kansas entrepreneurs.','https://jcccsbdc.com/become-a-client/','All stages','All industries','Business planning; training; growth','Kansas'),('KC BizCare','Business advising','City resource for business registration, zoning, licensing and local assistance.','https://bizcare.kcmo.gov/','All stages','All industries','Permits; licensing; starting a business','Kansas City, MO'),('SCORE Kansas City','Mentoring','Business mentoring and workshops for local entrepreneurs.','https://www.score.org/mo/kansas-city/','All stages','All industries','Mentoring; training; business planning','KC metro'),('Enterprise Center in Johnson County','Business advising','Entrepreneur education, mentoring and connections to capital across the region.','https://www.ecjc.com/','All stages','All industries','Mentoring; financing guidance; training','KC metro'),('Growth Mentoring Service','Mentoring','Team-based mentoring for companies looking to scale, including eligible early-stage technology firms.','https://www.ecjc.com/entrepreneurs/programs/gms/','Growth','All industries','Mentoring; strategy; scaling','KC metro'),('Helzberg Entrepreneurial Mentoring Program','Mentoring','Long-term CEO mentorship for established growth-oriented businesses; eligibility requirements apply.','https://www.hempkc.org/','Established business','All industries','CEO mentoring; leadership; scaling','KC metro'),('ScaleUP! KC','Accelerators & growth programs','Cohort-based coaching, peer learning and strategy training for qualifying growing businesses.','https://sbdc.umkc.edu/scaleup-kc/','Growth','All industries','Scaling; coaching; peer learning','KC metro'),('LaunchKC','Accelerators & growth programs','Startup grant competition and support for innovative companies willing to locate in Kansas City, Missouri. Check the next application window.','https://www.launchkc.org/competition/','Early stage','Technology','Funding; mentoring; startup growth','Kansas City, MO'),('Pipeline Entrepreneurs','Accelerators & growth programs','Founder development, mentorship and programming for Midwest entrepreneurs.','https://www.pipelineentrepreneurs.com/about','Growth','All industries','Founder development; mentoring; network','Midwest'),('Digital Sandbox KC','Commercialization & prototyping','Proof-of-concept resources for technology commercialization, market validation and prototypes. Confirm current program availability.','https://www.kcdigitaldrive.org/project/digital-sandbox/','Early stage','Technology','Prototype; commercialization; validation','KC metro'),('Regnier Idea Lab','Commercialization & prototyping','UMKC founder collaboration space for developing business and product ideas.','https://info.umkc.edu/regnier/regnier-innovators-hub/','Idea stage','All industries','Idea development; mentoring; founder network','Kansas City, MO'),('KC BioHub','Industry-specific support','Biomanufacturing and biologics consortium connecting regional industry, research and workforce organizations.','https://kcbiohub.org/about-us/','All stages','Life sciences','Industry connections; research; commercialization','KC metro'),('AltCap','Financing assistance','Community lender offering small-business financing and loan-readiness assistance; terms and eligibility vary.','https://altcap.org/','All stages','All industries','Debt financing; loan readiness','Kansas & Missouri'),('Spark Kansas City','Workspace & facilities','Downtown shared offices and workspace for entrepreneurs, creators and growing teams.','https://sparkcoworking.com/kansas-city/','All stages','All industries','Workspace; networking','Kansas City, MO'),('EDCKC','Economic development','Business expansion, site selection, incentives and technical assistance in Kansas City, Missouri.','https://edckc.com/','Growth','All industries','Expansion; incentives; site selection','Kansas City, MO')) insert into public.ecosystem_providers(tenant_id,name,category,description,website,stage,industry,needs,area,source,reviewed,status) select t.id,s.name,s.category,s.description,s.website,s.stage,s.industry,string_to_array(s.needs,'; '),s.area,s.website,'2026-11-27','published' from src s cross join public.tenants t where t.slug='back2kc' on conflict(tenant_id,name) do nothing;